 for(const b of w.bullets){if(b.id===3||b.id===6){img('BUL_HeliBullet_01',b.x-17,b.y-6,34,12);ctx.fillStyle='#ee9e26';ctx.fillRect(b.x-24,b.y-3,10,6);}else if(b.id===4){img('BUL_GrenadeArrow_01',b.x-23,b.y-7,46,14);}else if(b.id===7){ctx.strokeStyle='#36b8e6';ctx.lineWidth=7;ctx.beginPath();ctx.arc(b.x-18,b.y,37,-1.15,1.15);ctx.stroke();}else if(b.id===8){ctx.fillStyle='#55bde8';ctx.fillRect(b.x-26,b.y-5,52,10);ctx.fillStyle='#d0f2ff';ctx.fillRect(b.x-24,b.y-2,48,4);}else if(b.id===9){sprite('CHR_Run_04',b.x,b.y+45,.65,false,.45);}else{ctx.strokeStyle='#1a4b7d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(b.x-16,b.y);ctx.lineTo(b.x+6,b.y);ctx.stroke();}}
