function button(label,fn,cls='ink'){const b=document.createElement('button');b.className=cls;b.textContent=label;b.onclick=()=>{sfx('click');fn();};return b;}
function screen(title,{close=menu,balance=false}={}){ui.innerHTML='';const s=document.createElement('section');s.className='screen';const h=document.createElement('header');const t=document.createElement('h1');t.textContent=title;h.append(t);if(balance){const bal=document.createElement('span');bal.className='balance';bal.textContent=`◉ ${fmt(save.coins)}`;h.append(bal);}const b=button('×',close,'');b.setAttribute('aria-label','Back');h.append(b);s.append(h);const c=document.createElement('div');c.className='content';s.append(c);ui.append(s);return {s,c,h};}
function menu(){if(world&&!ended)finishRun(true);state='menu';world=null;resetInput();ui.innerHTML='';setMusic('M_0001_Menu.mp3');const spots=[['Play',playSelect,32.1,49,35.5,17],['Shop',()=>shop('menu'),35,66.3,29.4,13.8],['Scores',scores,65.7,69,29.3,11.6],['Tutorial',()=>startRun(true),35.5,81.2,29.8,10.7],['Options',settings,65.6,81,29.6,11.6],['About',about,4.4,81.1,28.6,11.8]];for(const [label,fn,left,top,width,height]of spots){const b=button(label,fn,'hit');b.setAttribute('aria-label',label);b.style.cssText=`left:${left}%;top:${top}%;width:${width}%;height:${height}%`;ui.append(b);}if(!storageOK)toast('Browser storage is unavailable. Progress will last for this session.');}
function playSelect(){state='select';const {s,c}=screen('Choose your weapon',{balance:true});const grid=document.createElement('div');grid.className='grid';for(const w of WEAPONS){const unlocked=save.unlocked.includes(w.id),selected=save.selected===w.id;const card=document.createElement('article');card.className=`card${selected?' selected':''}`;card.innerHTML=`<img src="${ICON('CHR_Run'+(w.skin==='Clone'?'':w.skin==='Super'?'':'N'+w.skin)+'_01')}" alt="" onerror="this.src='icons/${w.id===8?'CHR_SuperSketchman_01':'CHR_Run_01'}.png'"><h2>${w.name}</h2><p>${w.desc}</p><span class="price">${unlocked?(selected?'Equipped':'Unlocked'):`◉ ${fmt(w.cost)}`}</span>`;const b=button(unlocked?'Select':`Unlock`,()=>{if(buyWeapon(save,w.id)){persist();playSelect();}else toast(`You need ${fmt(w.cost-save.coins)} more coins.`);});if(selected)b.disabled=true;card.append(b);grid.append(card);}c.append(grid);const a=document.createElement('div');a.className='actions';a.append(button('Missions',missionScreen),button('Run →',()=>startRun(),'ink primary'));s.append(a);}
function attachHud(){ui.innerHTML='';const make=(label,n,cls)=>{const b=document.createElement('button');b.className=`hud-button ${cls}`;b.setAttribute('aria-label',label);b.innerHTML=`<img src="${ICON(n)}" alt="">`;ui.append(b);return b;};const j=make('Jump. Press twice to double jump, third press and hold to glide.','HUD_JumpButton_01','jump');const f=make('Fire. Hold to shoot.','HUD_FireButton_01','fire');const p=make('Pause','HUD_PauseBtn_01','pause');p.onclick=pause;for(const [el,type]of [[j,'jump'],[f,'fire']]){el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);if(type==='jump'){pointerJump.add(e.pointerId);world.jump();world.jumpHeld=true;}else{pointerFire.add(e.pointerId);if(world.cooldown<=0)world.shoot();}syncInput();});const release=e=>{(type==='jump'?pointerJump:pointerFire).delete(e.pointerId);syncInput();};el.addEventListener('pointerup',release);el.addEventListener('pointercancel',release);el.addEventListener('lostpointercapture',release);}
 const weapon=button(world.weapon.name,()=>{pause();},'weapon');weapon.setAttribute('aria-label',`Current weapon: ${world.weapon.name}. Pause`);ui.append(weapon);}
function resetInput(){pointerJump.clear();pointerFire.clear();keys.clear();if(world){world.fireHeld=false;world.releaseJump();}}
function syncInput(){if(!world)return;world.fireHeld=pointerFire.size>0||keys.has('KeyX')||keys.has('ArrowRight')||keys.has('KeyD');world.jumpHeld=pointerJump.size>0||keys.has('Space')||keys.has('ArrowUp')||keys.has('KeyW');if(!world.jumpHeld)world.gliding=false;}
function activeMissions(){return save.missionIndex.map(id=>missions[id]).filter(Boolean);}
function missionEligible(m,type,sub){if(m.event!==type)return false;const t=m.text.toLowerCase();if(t.includes('without shooting')&&world.shots>0)return false;if(t.includes('without collecting')&&world.coins>0)return false;if(t.includes('magnet')&&!world.effects.magnet)return false;if(type==='Died'){const between=t.match(/between (\d+)m and (\d+)m/);if(between)return world.distance>=+between[1]&&world.distance<=+between[2];if(t.includes('bloody'))return !!world.effects.blood;}
 if(type==='FireWeapon'){const names={pistol:0,shotgun:1,smg:2,rpg:3,'explosive arrows':4};for(const [word,id]of Object.entries(names))if(t.includes(word)&&sub!==id)return false;}
 if(type==='DestroyedStaticHazard'||type==='SmashIntoStaticHazard'||type==='NearMissStaticHazard'){const names={crate:0,barrel:1,'spike board':2,'land mine':3,saw:4,'air mine':5,'junk pile':6,'death ray':7};for(const [word,id]of Object.entries(names))if(t.includes(word)&&sub!==id)return false;}
 if(type==='KilledMovingEnemy'){if(t.includes('jet')&&sub!==1)return false;if((t.includes('sword')||t.includes('knife'))&&sub!==0)return false;}return true;}
function event(type,amount=1,sub=0){if(['shoot','jump','coin','hit','destroy','explosion','health','shield','revive'].includes(type))sfx(type,sub);if(type==='bossStart'){setMusic('M_0003_Boss.wav');toast('BOSS INCOMING!');}if(type==='bossEnd'){setMusic('M_0002_InGame.wav');toast('Boss defeated! +100 coins');}if(type==='revive')toast('Extra life! Back in action.');if(type==='Died'){resetInput();setMusic('M_0004_GameOverLoop.wav');}
 if(!missions.length||!world)return;if(['GotCoin','GotHP','Ran1Meter','Glide1Meter','BossKill','FireWeapon','KilledMovingEnemy','DestroyedStaticHazard','PlayGame'].includes(type))save.totals[type]=(save.totals[type]||0)+amount;
 for(const m of activeMissions()){if(save.completed.includes(m.id)||pendingMission.includes(m.id)||!missionEligible(m,type,sub))continue;const key=String(m.id);let inc=amount;if(type==='Died')inc=m.target;save.missionProgress[key]=(save.missionProgress[key]||0)+inc;if(save.missionProgress[key]>=m.target){pendingMission.push(m.id);save.completed.push(m.id);save.coins+=m.reward;sfx('complete');toast(`Mission complete!\n${m.text}\n+${fmt(m.reward)} coins`);persist();}}
}
function advanceMissions(){for(let i=0;i<3;i++){while(save.completed.includes(save.missionIndex[i])&&save.missionIndex[i]<(i+1)*40)save.missionIndex[i]++;if(save.missionIndex[i]>=(i+1)*40)save.missionIndex[i]=-1;}}
function startRun(isTutorial=false){resetInput();tutorial=isTutorial;pendingMission=[];advanceMissions();for(const m of activeMissions())if(!m.cumulative)save.missionProgress[m.id]=0;let effects={};const map={double:{doubleCoins:true},magnet:{magnet:true},blood:{blood:true},armor:{armor:2},megaArmor:{armor:3},power:{power:2},megaPower:{power:3},glide:{glide:true},life:{life:true},head500:{headstart:500},head750:{headstart:750},head1000:{headstart:1000},head1250:{headstart:1250},head1500:{headstart:1500}};for(const id of save.equipped){if((save.stock[id]||0)>0&&map[id]){Object.assign(effects,map[id]);save.stock[id]--;}}effects.longShield=!!save.permanent.longShield;effects.fullHealth=!!save.permanent.fullHealth;world=new World({weapon:save.selected,onEvent:event,effects});state='playing';ended=false;save.runs++;world.event('PlayGame');persist();attachHud();muteForPause=false;setMusic('M_0002_InGame.wav');tipTime=0;}
function finishRun(abandon=false){if(!world||ended)return;ended=true;save.coins+=world.coins;save.best=Math.max(save.best,Math.floor(world.distance));save.scores.push({distance:Math.floor(world.distance),coins:world.coins,kills:world.kills,weapon:world.weapon.id,date:new Date().toISOString()});save.scores.sort((a,b)=>b.distance-a.distance);save.scores=save.scores.slice(0,10);persist();if(!abandon)gameOver();}
function gameOver(){state='over';resetInput();const {s,c}=screen('Game Over',{close:menu,balance:true});s.classList.add('center');c.style.flex='initial';c.innerHTML=`<p>${Math.floor(world.distance)>=save.best?'A new line in the record book.':'One more run. One more page.'}</p><div class="stats"><div><strong>${fmt(world.distance)}m</strong><span>DISTANCE</span></div><div><strong>${fmt(world.coins)}</strong><span>COINS</span></div><div><strong>${world.kills}</strong><span>ENEMIES</span></div></div><p>Personal best: <b>${fmt(save.best)}m</b></p>`;const a=document.createElement('div');a.className='actions';a.append(button('Menu',menu),button('Weapons',playSelect),button('Retry →',()=>startRun(),'ink primary'));s.append(a);const b=button('Share score',async()=>{const message=`I ran ${fmt(world.distance)}m in Sketchman!`;try{if(navigator.share)await navigator.share({title:'Sketchman',text:message,url:location.href});else{await navigator.clipboard.writeText(`${message} ${location.href}`);toast('Score and link copied.');}}catch{toast(message);}});c.append(b);}
function pause(){if(state!=='playing')return;state='paused';resetInput();muteForPause=true;updateMusic();const overlay=document.createElement('div');overlay.className='paused';ui.append(overlay);const panel=document.createElement('section');panel.className='screen center';panel.innerHTML='<h1>Paused</h1>';const a=document.createElement('div');a.className='actions';a.append(button('Resume →',resume,'ink primary'),button('Shop',()=>shop('paused')),button('Restart',()=>{finishRun(true);startRun();}),button('Menu',()=>{finishRun(true);menu();}));panel.append(a);overlay.append(panel);}
function resume(){if(!world||world.dead)return;state='playing';resetInput();attachHud();muteForPause=false;updateMusic();last=performance.now();}
